programs.git:
#!/bin/sh
place='<place>'
case "$1" in
  rev-parse) step=head ;;
  status) step=status ;;
  ls-files) step=listing ;;
  -C) step=stage ;;
  *) step=other ;;
esac
if [ -f "$place/fake/git.$step.count" ]; then count=$(/bin/cat "$place/fake/git.$step.count"); else count=0; fi
count=$((count + 1))
printf '%s\n' "$count" > "$place/fake/git.$step.count"
{
  printf 'call %s %s\n' "$step" "$count"
  printf 'cwd %s\n' "$(pwd -P)"
  for argument in "$@"; do printf 'argument %s\n' "$argument"; done
} >> "$place/fake/git.log"
answer="$place/fake/git/$step"
if [ -f "$answer.$count.sh" ]; then . "$answer.$count.sh"; elif [ -f "$answer.sh" ]; then . "$answer.sh"; fi
if [ -f "$answer.$count.stdout" ]; then /bin/cat "$answer.$count.stdout"; elif [ -f "$answer.stdout" ]; then /bin/cat "$answer.stdout"; fi
if [ -f "$answer.$count.status" ]; then exit "$(/bin/cat "$answer.$count.status")"; fi
if [ -f "$answer.status" ]; then exit "$(/bin/cat "$answer.status")"; fi
exit 0

